const tabId = 480038429;

// Let's extract the video items from YouTube search results
const results = await browserjs(tabId, () => {
  const videoElements = document.querySelectorAll('ytd-video-renderer');
  const items = [];

  videoElements.forEach(el => {
    const titleEl = el.querySelector('#video-title');
    const channelEl = el.querySelector('#channel-name, ytd-channel-name');
    const metadataLine = el.querySelectorAll('#metadata-line span');

    let viewCountText = '';
    let ageText = '';
    if (metadataLine.length >= 1) viewCountText = metadataLine[0].textContent.trim();
    if (metadataLine.length >= 2) ageText = metadataLine[1].textContent.trim();

    // Also let's check aria-label on titleEl which often has exact view count
    const ariaLabel = titleEl ? titleEl.getAttribute('aria-label') : '';

    // Duration
    const durationEl = el.querySelector('ytd-thumbnail-overlay-time-status-renderer, #time-status');
    const duration = durationEl ? durationEl.textContent.trim() : '';

    if (titleEl && titleEl.href) {
      items.push({
        title: titleEl.textContent.trim(),
        href: titleEl.href,
        channel: channelEl ? channelEl.textContent.trim() : '',
        viewCountText,
        ageText,
        ariaLabel,
        duration
      });
    }
  });

  return items;
});

console.log(`Found ${results.length} video results:`);
console.log(JSON.stringify(results.slice(0, 15), null, 2));

