  // Title
  const titleEl = document.querySelector('h1.ytd-watch-metadata, #title h1, h1.title');
  const title = titleEl ? titleEl.textContent.trim() : document.title;

  // Channel
  const channelEl = document.querySelector('ytd-channel-name #text, #owner-name a, #channel-name a');
  const channel = channelEl ? channelEl.textContent.trim() : '';

  // View count
  const viewCountEl = document.querySelector('#info-container #count, #description-inner #info span, ytd-watch-info-text, #info-strings yt-formatted-string, #count span');
  const infoText = viewCountEl ? viewCountEl.textContent.trim() : '';

  // Let's also look for any element containing "views"
  const allSpans = Array.from(document.querySelectorAll('span, yt-formatted-string'));
  const viewSpans = allSpans.map(s => s.textContent.trim()).filter(t => t.includes('views') && /\d/.test(t));

  return {
    url: window.location.href,
    title,
    channel,
    infoText,
    viewSpans: viewSpans.slice(0, 10)
  };
});

